def build_artwork(asset_dir: Path) -> None:
    for name, body in ART.items():
        svg = f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 680 820" role="img" aria-labelledby="title desc"><title id="title">OFFSCRIPT {name.replace('-', ' ')}</title><desc id="desc">Original geometric campaign illustration about {name.replace('-', ' ')}.</desc>{body}<rect width="680" height="820" fill="#f4f0e3" opacity=".025"/><path d="M0 0H680V820H0z" fill="none" stroke="#f4f0e3" stroke-opacity=".25" stroke-width="2"/></svg>'''
        (asset_dir / f"{name}.svg").write_text(svg, encoding="utf-8")
